// The achievement catalog. Source of truth in code (seeded into DB for global
// counts + admin visibility, like cosmetics). Tiered tracks are generated by
// the `series()` helper so ~30 tracks × 5 tiers + standalones + secrets stay
// DRY. Each tier of a series is its own achievement id ("snake-score-3").
import {
  ARCADE_FLOOR_GROUPS,
  isOnFloor,
} from '@/features/arcade/components/arcade-game-registry';
import type { StoreRarity } from '@/features/arcade/lib/rewards';
import {
  GLOBAL,
  MP,
  DAILY,
  gameStat,
  groupPlayedStat,
  secretStat,
} from '@/server/arcade/stats/stat-keys';
import { badgeIconFor } from './badges';
import {
  TIER_LABELS,
  type AchievementCategory,
  type AchievementDef,
} from './types';

const TIER_XP = [120, 250, 500, 1000, 2000];
const TIER_RARITY: StoreRarity[] = ['common', 'common', 'rare', 'epic', 'legendary'];

/** An achievement's display name: a capital first letter and the rest in
 *  lowercase ("Hello, world", "Serpentine 3"). Ids never change with it. */
function sentenceCase(name: string): string {
  const lower = name.toLowerCase();
  return lower.charAt(0).toUpperCase() + lower.slice(1);
}

type SeriesOpts = {
  id: string;
  name: string;
  category: AchievementCategory;
  stat: string;
  thresholds: number[]; // up to 5, ascending (descending for direction:'low')
  direction?: 'low'; // lower stat is better -> lte condition
  /** Unused. Badges are drawn from the id (badges.ts); the per-achievement PNGs are no longer shown. */
  icon?: string;
  /** Store item id granted at the final tier. */
  topCosmetic?: string;
  blurb: (threshold: number, tier: number) => string;
  /** Off the floor whatever its game: listed only for players who earned it. */
  retired?: boolean;
};

/* A series belongs to the game its stat is named for ("snake.best" -> snake).
   Cross-game stats (global, mp, daily) belong to no game. */
const NO_GAME_SCOPES = new Set(['global', 'mp', 'daily']);
function gameOfStat(stat: string): string | undefined {
  const scope = stat.split('.')[0];
  return NO_GAME_SCOPES.has(scope) ? undefined : scope;
}

function series(opts: SeriesOpts): AchievementDef[] {
  const game = gameOfStat(opts.stat);
  return opts.thresholds.map((threshold, i) => {
    const isTop = i === opts.thresholds.length - 1;
    return {
      id: `${opts.id}-${i + 1}`,
      seriesId: opts.id,
      tier: i + 1,
      tierLabel: TIER_LABELS[i],
      name: `${sentenceCase(opts.name)} ${i + 1}`,
      description: opts.blurb(threshold, i + 1),
      category: opts.category,
      hidden: false,
      rarity: TIER_RARITY[i],
      xp: TIER_XP[i],
      cosmeticId: isTop ? opts.topCosmetic : undefined,
      icon: badgeIconFor(`${opts.id}-${i + 1}`, i + 1, opts.id),
      game,
      retired: opts.retired,
      condition:
        opts.direction === 'low'
          ? { stat: opts.stat, lte: threshold }
          : { stat: opts.stat, gte: threshold },
    };
  });
}

type StandaloneOpts = {
  id: string;
  name: string;
  description: string;
  category: AchievementCategory;
  rarity: StoreRarity;
  xp: number;
  condition: AchievementDef['condition'];
  icon?: string;
  cosmeticId?: string;
  hidden?: boolean;
  hint?: string;
  secretTriggerKey?: string;
  retired?: boolean;
};

function standalone(opts: StandaloneOpts): AchievementDef {
  return {
    id: opts.id,
    tier: 0,
    name: sentenceCase(opts.name),
    description: opts.description,
    category: opts.category,
    hidden: opts.hidden ?? false,
    rarity: opts.rarity,
    xp: opts.xp,
    cosmeticId: opts.cosmeticId,
    icon: badgeIconFor(opts.id, 0),
    condition: opts.condition,
    hint: opts.hint,
    secretTriggerKey: opts.secretTriggerKey,
    retired: opts.retired,
  };
}

/** A secret/easter-egg gated on a `secret.<key>` trigger counter reaching `count`. */
function secret(opts: {
  id: string;
  name: string;
  description: string;
  triggerKey: string;
  count?: number;
  rarity?: StoreRarity;
  xp?: number;
  cosmeticId?: string;
  hint?: string;
  retired?: boolean;
}): AchievementDef {
  return standalone({
    retired: opts.retired,
    id: opts.id,
    name: opts.name,
    description: opts.description,
    category: 'secret',
    rarity: opts.rarity ?? 'epic',
    xp: opts.xp ?? 400,
    hidden: true,
    hint: opts.hint,
    icon: 'secret',
    cosmeticId: opts.cosmeticId,
    secretTriggerKey: opts.triggerKey,
    condition: { stat: secretStat(opts.triggerKey), gte: opts.count ?? 1 },
  });
}

const ms = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(n % 1000 ? 1 : 0)}s` : `${n}ms`);

