export const ACHIEVEMENTS: AchievementDef[] = [
  ...SERIES,
  ...STANDALONE,
  ...FLOOR_GROUP_FEATS,
  ...SECRETS,
];

/** Off the floor: not listed to anyone who hasn't earned it. A series follows
 *  its game, so a reserve game's series still unlocks for players who find it
 *  by link and lands on the retired shelf; if the game returns to the floor,
 *  the series is listed again. */
export function isRetiredAchievement(def: AchievementDef): boolean {
  if (def.retired) return true;
  return def.game !== undefined && !isOnFloor(def.game);
}

export const ACHIEVEMENTS_BY_ID: Map<string, AchievementDef> = new Map(
  ACHIEVEMENTS.map((a) => [a.id, a]),
);

/** Allowlist of valid secret trigger keys (for /api/achievements/trigger). */
export const SECRET_TRIGGER_KEYS: Set<string> = new Set(
  ACHIEVEMENTS.flatMap((a) => (a.secretTriggerKey ? [a.secretTriggerKey] : [])),
);

export function getAchievement(id: string): AchievementDef | undefined {
  return ACHIEVEMENTS_BY_ID.get(id);
}
